#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353;

long long fastExpo(long long base, long long exp) {
    long long result = 1;
    long long cur = base % mod;
    long long e = exp;
    while (e > 0) {
        if (e & 1) {
            result = (result * cur) % mod;
        }
        cur = (cur * cur) % mod;
        e >>= 1;
    }
    return result;
}

long long modInv(long long x) {
    return fastExpo(x, mod - 2);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long N, M, L, R;
    cin >> N >> M >> L >> R;

    long long length = R - L + 1;
    long long E = (length / 2) + ((R % 2 == 0 && L % 2 == 0) ? 1 : 0);
    long long O = length - E;

    long long ans;
    if ((N * M) % 2 == 1) {
        ans = fastExpo(E + O, N * M);
    } else {
        long long sum = (fastExpo(E + O, N * M) + fastExpo(E - O, N * M)) % mod;
        ans = (sum * modInv(2)) % mod;
    }
    cout << ans << "\n";
    return 0;
}
